import {t,getLanguage} from './i18n.mjs';
import {range,copyText} from './estimator.mjs';

export function guideAnswer(question,{result,property,place}){
  const q=question.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').trim();
  if(/websites?|inonda\.(site|org|homes)|ιστοτοπ|са[йи]т|אתר|site.uri/.test(q))return {text:'All three websites belong to INONDA LTD: inonda.site explains property management, inonda.org covers repairs and renovation services, and inonda.homes helps you plan a budget. Use our website links to continue in your chosen language, then contact the same INONDA team for an inspection and written offer.',action:'network',label:'Explore INONDA websites'};
  if(/contact|whats|viber|phone|call|email|book|quote|appointment|speak|human|irina|constantin|επικοιν|τηλεφ|επιθεωρ|κλεισ|προσφορα|telefon|связ|контакт|звон|огляд|осмотр|oferta|program|зв.яз|התקשר|קשר|טלפון|בדיק|לקבוע|לתאם|תיאום|הצעת/.test(q))return {text:'Talk through your plan with Irina on +357 94 091 616 or Constantin on +357 94 091 613. Both contact lines have WhatsApp, Viber and call buttons. You can also email inonda2026@outlook.com. Our team confirms the scope, site assessment and written quote; this guide cannot make a booking.',action:'contact',label:'Choose your contact'};
  if(/\bvat\b|\btax\b|φπα|\btva\b|ндс|пдв|מע.מ/.test(q))return {text:'All prices in the budget planner include materials, installation and 19% VAT. VAT is never added again.',action:'estimate',label:'View my budget'};
  if(/warrant|guarant|εγγυ|гарант|garant|אחריות|registration|he490415|εγγραφ/.test(q))return {text:'INONDA LTD is registered in Cyprus as HE490415 and provides services across Cyprus. The company website states a written workmanship warranty of at least 6 months on labour. Ask the team to confirm the warranty terms in your written offer.',action:'contact',label:'Choose your contact'};
  if(/where|area|location|cyprus|nicosia|limassol|address|based|strovolos|larnaca|paphos|που|κυπρ|λευκωσ|λεμεσ|адрес|кипр|кіпр|unde|adresa|locati|איפה|כתובת|קפריס/.test(q))return {text:'INONDA is based in Strovolos, Nicosia, and works across Cyprus. Add the town or village of the job in the planner to see your total budget.',action:'property',label:'Add the job location'};
  if(/price|cost|budget|much|pay|current|estimate now|τιμη|κοστο|ποσο|προυπολογ|pret|стоим|бюджет|варт|ціна|кошту|скільки|תקציב|מחיר|עלות|cat costa|buget/.test(q)){
    if(result.errors.length)return {text:'Please check the highlighted property or service inputs first. Once they are valid, I can explain your current planning budget.',action:'property',label:'Check my inputs'};
    if(!result.rows.length)return {text:'Tick one or more jobs in the budget planner to start your budget.',action:'property',label:'Choose jobs'};
    if(result.needsPlace)return {text:'Add the town or village of the job so the planner can show your total budget.',action:'property',label:'Add the job location'};
    const lang=getLanguage();
    return {text:t('For your {property} property in {location}, your current budget is {range}, including materials, installation and 19% VAT. This is a planning guide; INONDA LTD gives a written offer after inspecting the property.',{property:copyText(lang,property),location:place,range:range(result.oneOff)}),action:'estimate',label:'View my budget'};
  }
  if(/commercial|office|shop|business|residential|villa|apartment|επαγγελμα|κατοικ|γραφει|коммерч|жило|комерц|житло|rezident|birou|מגורים|מסחר/.test(q))return {text:'Choose Residential for an apartment, villa or house, or Commercial for an office, shop or shared facility. The budget adjusts to the property type you choose.',action:'property',label:'Choose jobs'};
  if(/alumin|window|shutter|pergola|\bhpl\b|cladding|facade|panel|\bwpc\b|\bpvc\b|αλουμιν|κουφωμ|πανελ|алюмин|алюмін|окн|вікн|панел|אלומיניום|פאנל|ferestr|panou|placar/.test(q))return {text:'Aluminium works, HPL cladding and decorative panels are priced per m², with materials, workmanship and 19% VAT in one rate. Choose the system in each service scope; a site survey and final measurements confirm the quote.',action:'services',label:'Explore aluminium & panels'};
  if(/clean|καθαρ|уборк|прибиран|curat|ניקיון|manage|tenant|landlord|διαχειρ|управл|administr|ניהול|garden|landscap|κηπ|сад|gradin|גינון|maintain|maintenance|handyman|urgent|small repair|συντηρ|обслуж|intretin|תחזוק|month|weekly|recurr|frequency|μηνι|εβδομαδ|месяц|місяц|lunar|חודש/.test(q))return {text:'Cleaning, gardening, maintenance, property management, small repairs and urgent repairs are provided only under a maintenance or management contract, so they are not part of the budget planner. Contact INONDA to discuss a contract.',action:'contact',label:'Contact INONDA'};
  if(/renovat|kitchen|bathroom|refurb|paint|tiling|floor|gypsum|plaster|plumb|electri|roof|waterproof|door|carpent|outdoor|paving|repair|ανακαιν|κουζιν|μπανι|βαψ|γυψ|υδραυλ|ηλεκτρ|στεγ|πορτ|ремонт|кухн|ванн|покрас|гипс|сантех|электр|кровл|двер|renovar|bucatar|baie|zugrav|rigips|שיפו|מטבח|גבס|חשמל|אינסטל/.test(q))return {text:'Flooring, kitchens, bathrooms, painting, gypsum board, plumbing, electrical, roofing, doors and outdoor works are all in the budget planner, with aluminium, HPL, decorative panels and renovation. Choose the type of work, the size and how complex the job is; every price includes materials and installation.',action:'services',label:'Choose jobs'};
  if(/save|download|print|pdf|compare|αποθηκε|ληψη|εκτυπ|скачат|завантаж|зберег|descarc|salv|הורד|שמיר/.test(q))return {text:'Use “Save as PDF” to keep a copy of your budget, or “Book an inspection” to send your list of jobs to INONDA on WhatsApp.',action:'estimate',label:'View my budget'};
  return {text:'Choose your property type and location, then tick the jobs you need. Your budget updates instantly, including materials, installation and 19% VAT. I can also help with services and contacting the team.',action:'property',label:'Start my budget'};
}

export function initAssistant({getEstimate}){
  const dialog=document.querySelector('#assistant-dialog'),toggle=document.querySelector('#assistant-toggle'),close=document.querySelector('#assistant-close'),log=document.querySelector('#assistant-log'),input=document.querySelector('#assistant-input');
  function message(text,visitor=false,answer){
    const row=document.createElement('div');row.className=visitor?'assistant-message visitor':'assistant-message';
    const name=document.createElement('small');name.textContent=visitor?'You':'INONDA guide';const body=document.createElement('p');body.textContent=text;if(visitor)body.dataset.noI18n='';row.append(name,body);
    if(answer?.action){const button=document.createElement('button');button.textContent=answer.label;button.addEventListener('click',()=>{const target={contact:'#contact',estimate:'#budget-card',property:'#property',services:'#services',network:'#inonda-network'}[answer.action];dialog.close();document.querySelector(target)?.scrollIntoView({behavior:'smooth'});});row.append(button);}
    log.append(row);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight;});
  }
  function ask(question,displayQuestion=question){if(!question.trim())return;const answer=guideAnswer(question.slice(0,300),getEstimate());message(displayQuestion.slice(0,300),true);message(answer.text,false,answer);input.value='';input.focus();}
  toggle.addEventListener('click',()=>{if(dialog.open){dialog.close();return;}dialog.show();toggle.setAttribute('aria-expanded','true');if(!log.children.length)message('Hello. I’m INONDA’s automated guide. Build your own estimate, explore what each service covers, or find the right person to contact. What would you like to plan?');input.focus();});
  close.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{toggle.setAttribute('aria-expanded','false');toggle.focus();});
  dialog.addEventListener('keydown',event=>{if(event.key==='Escape')dialog.close();});
  document.querySelector('#assistant-form').addEventListener('submit',event=>{event.preventDefault();ask(input.value);});
  document.addEventListener('inonda:language',()=>{log.replaceChildren();if(dialog.open)message(t('Hello. I’m INONDA’s automated guide. Build your own estimate, explore what each service covers, or find the right person to contact. What would you like to plan?'));});
  document.querySelectorAll('[data-question]').forEach(button=>button.addEventListener('click',()=>ask(button.dataset.question,button.textContent.trim())));
}
